struct _List_node_base {
  _List_node_base *next;
  _List_node_base *prev;
};

template<class T> struct _List_node : _List_node_base { T data; };

template<class T> class list {
  _List_node_base node;
public:
  class iterator {
    _List_node_base *p;
  public:
    iterator(_List_node_base *n = 0) : p(n) {}
    T &operator*() const { return ((_List_node<T> *)p)->data; }
    iterator &operator++() { p = p->next; return *this; }
    bool operator!=(const iterator &x) const { return p != x.p; }
    friend class list<T>;
  };
  iterator begin() { return iterator(node.next); }
  iterator end() { return iterator(&node); }
  void erase(iterator x) {
    x.p->next->prev = x.p->prev;
    x.p->prev->next = x.p->next;
    operator delete(x.p);
  }
};

