{
  list<ai_interface *>::iterator ai = all_ai_interfaces.begin();
  while(ai != all_ai_interfaces.end())
  {
    if(*ai == this)
    {
      all_ai_interfaces.erase(ai);
      break;
    }
    else
      ++ai;
  }

